// @ApexApiVersion 67.0
public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields cannot be null or empty.');
        }
        if (String.isBlank(objectApiName)) {
            throw new SearchException('objectApiName cannot be blank.');
        }

        DescribeSObjectResult describe;
        try {
            describe = Schema.describeSObject(objectApiName, true);
        } catch (Exception e) {
            throw new SearchException('Object does not exist or is not accessible: ' + objectApiName);
        }

        if (!describe.isAccessible()) {
            throw new SearchException('User does not have read access to object: ' + objectApiName);
        }

        // Build case-insensitive field lookup maps
        Map<String, DescribeFieldResult> fieldResultMap = new Map<String, DescribeFieldResult>();
        Map<String, String> fieldNameMap = new Map<String, String>();
        for (String fieldName : describe.fields.getMap().keySet()) {
            String lower = fieldName.toLowerCase();
            fieldResultMap.put(lower, describe.fields.getMap().get(fieldName));
            fieldNameMap.put(lower, fieldName);
        }

        // Validate and build select fields (Id is always included)
        List<String> selectFields = new List<String>();
        Set<String> addedFields = new Set<String>();
        addedFields.add('Id');
        selectFields.add('Id');

        for (String field : fields) {
            if (String.isBlank(field)) {
                throw new SearchException('Field name cannot be blank.');
            }
            String lower = field.toLowerCase();
            String actualField = fieldNameMap.get(lower);
            if (actualField == null) {
                throw new SearchException('Field does not exist on object: ' + field);
            }
            if (!fieldResultMap.get(lower).isAccessible()) {
                throw new SearchException('Field is not readable: ' + field);
            }
            if (!addedFields.contains(actualField)) {
                addedFields.add(actualField);
                selectFields.add(actualField);
            }
        }

        // Validate filter keys
        if (filters != null && !filters.isEmpty()) {
            for (String filterField : filters.keySet()) {
                if (String.isBlank(filterField)) {
                    throw new SearchException('Filter field name cannot be blank.');
                }
                String lower = filterField.toLowerCase();
                String actualField = fieldNameMap.get(lower);
                if (actualField == null) {
                    throw new SearchException('Filter field does not exist on object: ' + filterField);
                }
                if (!fieldResultMap.get(lower).isAccessible()) {
                    throw new SearchException('Filter field is not readable: ' + filterField);
                }
                if (!fieldResultMap.get(lower).isFilterable()) {
                    throw new SearchException('Filter field cannot be filtered: ' + filterField);
                }
            }
        }

        // Validate order-by field
        if (!String.isBlank(orderByField)) {
            String lower = orderByField.toLowerCase();
            String actualField = fieldNameMap.get(lower);
            if (actualField == null) {
                throw new SearchException('OrderBy field does not exist on object: ' + orderByField);
            }
            if (!fieldResultMap.get(lower).isAccessible()) {
                throw new SearchException('OrderBy field is not readable: ' + orderByField);
            }
            if (!fieldResultMap.get(lower).isSortable()) {
                throw new SearchException('OrderBy field cannot be sorted: ' + orderByField);
            }
        }

        // Build SOQL query
        StringBuilder query = new StringBuilder();
        query.append('SELECT Id');
        for (String field : selectFields) {
            if (!field.equalsIgnoreCase('Id')) {
                query.append(', ').append(field);
            }
        }
        query.append(' FROM ').append(describe.getName());

        if (filters != null && !filters.isEmpty()) {
            query.append(' WHERE ');
            List<String> conditions = new List<String>();
            for (String filterField : filters.keySet()) {
                String lower = filterField.toLowerCase();
                String actualField = fieldNameMap.get(lower);
                Object value = filters.get(filterField);
                conditions.append(buildCondition(actualField, value));
            }
            query.append(String.join(' AND ', conditions));
        }

        if (!String.isBlank(orderByField)) {
            String lower = orderByField.toLowerCase();
            String actualField = fieldNameMap.get(lower);
            query.append(' ORDER BY ').append(actualField).append(' ASC');
        }

        query.append(' LIMIT ').append(maxRows);

        return Database.query(query.toString());
    }

    private static String buildCondition(String fieldName, Object value) {
        if (value == null) {
            return fieldName + ' = null';
        }

        String valueStr = escapeSingleQuotes(String.valueOf(value));

        if (value instanceof String) {
            return fieldName + ' = \'' + valueStr + '\'';
        } else if (value instanceof Boolean) {
            return fieldName + ' = ' + ((Boolean) value ? 'true' : 'false');
        } else if (value instanceof Integer || value instanceof Long) {
            return fieldName + ' = ' + value;
        } else if (value instanceof Decimal || value instanceof Double) {
            return fieldName + ' = ' + value;
        } else if (value instanceof Date) {
            Date d = (Date) value;
            return fieldName + ' = DATE(' + d.year() + ',' + d.month() + ',' + d.day() + ')';
        } else if (value instanceof Id) {
            return fieldName + ' = \'' + valueStr + '\'';
        } else {
            return fieldName + ' = \'' + valueStr + '\'';
        }
    }

    private static String escapeSingleQuotes(String input) {
        if (input == null) {
            return '';
        }
        return input.replace('\'', '\'\'');
    }
}
