/**
 * OrderPayloadParser
 * Parses e-commerce order JSON payloads into strongly-typed Apex objects
 * and generates acknowledgement responses.
 */
public class OrderPayloadParser {

    /**
     * Custom exception thrown for any payload parsing or validation failure.
     * This ensures that callers only ever see this exception type from the
     * public API methods.
     */
    public class PayloadException extends Exception {}

    /**
     * Represents a single order line item.
     * All members are public as required.
     */
    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    /**
     * Represents a parsed order.
     * All members are public as required.
     */
    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    /**
     * Parses a JSON order payload string into an Order object.
     *
     * @param body raw JSON string
     * @return populated Order instance
     * @throws PayloadException if the body is null/blank, invalid JSON,
     *                          not a JSON object, missing/blank number,
     *                          or any line is invalid.
     */
    public static Order parse(String body) {
        try {
            return doParse(body);
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Unexpected parsing error: ' + e.getMessage());
        }
    }

    /**
     * Generates a JSON acknowledgement string for a given Order.
     *
     * @param order the order to acknowledge
     * @return JSON string with keys: number, status, lineCount, total
     * @throws PayloadException if order is null
     */
    public static String toAcknowledgement(Order order) {
        if (order == null) {
            throw new PayloadException('Order cannot be null');
        }

        Map<String, Object> acknowledgement = new Map<String, Object>();
        acknowledgement.put('number', order.orderNumber);
        acknowledgement.put('status', 'RECEIVED');
        acknowledgement.put('lineCount', order.lines != null ? order.lines.size() : 0);
        acknowledgement.put('total', order.total != null ? order.total : 0);

        return JSON.serialize(acknowledgement);
    }

    /**
     * Core parsing logic separated from exception wrapping.
     */
    private static Order doParse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body cannot be null or blank');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON: ' + e.getMessage());
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Body must be a JSON object');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        // Required: order number
        Object numberObj = root.get('number');
        if (numberObj == null || !(numberObj instanceof String) || String.isBlank((String) numberObj)) {
            throw new PayloadException('Missing or blank order number');
        }
        String orderNumber = (String) numberObj;

        // Optional: order date (ISO yyyy-MM-dd)
        Date orderDate = null;
        Object dateObj = root.get('date');
        if (dateObj != null && dateObj instanceof String) {
            try {
                orderDate = Date.valueOf((String) dateObj);
            } catch (Exception e) {
                // Invalid date format, leave as null
            }
        }

        // Optional: currency code
        Object currencyObj = root.get('currency');
        String currencyCode = currencyObj instanceof String ? (String) currencyObj : null;

        // Optional: customer email
        String customerEmail = null;
        Object customerObj = root.get('customer');
        if (customerObj instanceof Map<String, Object>) {
            Object emailObj = ((Map<String, Object>) customerObj).get('email');
            customerEmail = emailObj instanceof String ? (String) emailObj : null;
        }

        // Lines: empty list when missing or null
        List<Line> lines = new List<Line>();
        Object linesObj = root.get('lines');
        if (linesObj != null && linesObj instanceof List<Object>) {
            List<Object> rawLines = (List<Object>) linesObj;
            for (Object lineObj : rawLines) {
                if (!(lineObj instanceof Map<String, Object>)) {
                    throw new PayloadException('Invalid line structure');
                }
                lines.add(parseLine((Map<String, Object>) lineObj));
            }
        }

        Order order = new Order();
        order.orderNumber = orderNumber;
        order.orderDate = orderDate;
        order.currencyCode = currencyCode;
        order.customerEmail = customerEmail;
        order.lines = lines;

        // Compute total as sum of rounded line totals
        Decimal total = 0;
        for (Line line : lines) {
            total += line.lineTotal;
        }
        order.total = total.setScale(2, RoundingMode.HALF_UP);

        return order;
    }

    /**
     * Parses a single line item map into a Line object.
     * Validates sku, quantity, and unitPrice per business rules.
     */
    private static Line parseLine(Map<String, Object> lineMap) {
        Line line = new Line();

        // SKU: required, must be a non-blank string
        Object skuObj = lineMap.get('sku');
        if (!(skuObj instanceof String) || String.isBlank((String) skuObj)) {
            throw new PayloadException('Missing or blank sku');
        }
        line.sku = (String) skuObj;

        // Quantity: required, must be a positive integer
        Object qtyObj = lineMap.get('quantity');
        if (qtyObj == null || !isValidInteger(qtyObj)) {
            throw new PayloadException('Missing or invalid quantity');
        }
        Integer quantity = toInteger(qtyObj);
        if (quantity <= 0) {
            throw new PayloadException('Quantity must be positive');
        }
        line.quantity = quantity;

        // Unit price: required, must be non-negative
        Object priceObj = lineMap.get('unitPrice');
        if (priceObj == null || !isNumeric(priceObj)) {
            throw new PayloadException('Missing or invalid unitPrice');
        }
        Decimal unitPrice = toDecimal(priceObj);
        if (unitPrice < 0) {
            throw new PayloadException('unitPrice must be non-negative');
        }
        line.unitPrice = unitPrice;

        // Discount: optional fraction, missing/null defaults to 0
        Object discountObj = lineMap.get('discount');
        Decimal discount = 0;
        if (discountObj != null) {
            if (!isNumeric(discountObj)) {
                throw new PayloadException('Invalid discount');
            }
            discount = toDecimal(discountObj);
        }
        line.discount = discount;

        // Line total: quantity * unitPrice * (1 - discount), rounded to 2 dp half-up
        Decimal lineTotal = quantity * unitPrice * (1 - discount);
        lineTotal = lineTotal.setScale(2, RoundingMode.HALF_UP);
        line.lineTotal = lineTotal;

        return line;
    }

    /**
     * Checks if an object is a valid integer value (Integer, Long, or Decimal with no fractional part).
     */
    private static Boolean isValidInteger(Object obj) {
        if (obj instanceof Integer || obj instanceof Long) {
            return true;
        }
        if (obj instanceof Decimal) {
            Decimal dec = (Decimal) obj;
            return dec == dec.setScale(0, RoundingMode.HALF_UP);
        }
        return false;
    }

    /**
     * Checks if an object is a numeric type.
     */
    private static Boolean isNumeric(Object obj) {
        return obj instanceof Integer || 
               obj instanceof Long || 
               obj instanceof Decimal || 
               obj instanceof Double;
    }

    /**
     * Converts a numeric object to Integer.
     */
    private static Integer toInteger(Object obj) {
        if (obj instanceof Integer) {
            return (Integer) obj;
        }
        if (obj instanceof Long) {
            return ((Long) obj).intValue();
        }
        return ((Decimal) obj).intValue();
    }

    /**
     * Converts a numeric object to Decimal.
     */
    private static Decimal toDecimal(Object obj) {
        return Decimal.valueOf(String.valueOf(obj));
    }
}
