@isTest
public class AddressVerificationServiceTest {

    /**
     * Records every callout made during a test so the request contract
     * (method, endpoint, headers, body) can be asserted. A response can be
     * pre-configured via {@link #setResponse}.
     */
    public class AddressApiMock implements HttpCallout {
        public List<HttpRequest> capturedRequests = new List<HttpRequest>();
        private HttpResponse responseToReturn;

        public HttpResponse respond(HttpRequest req) {
            capturedRequests.add(req);
            return responseToReturn;
        }

        public void setResponse(HttpResponse response) {
            responseToReturn = response;
        }
    }

    @isTest
    public static void testBlankBillingStreetIsSkipped() {
        AddressApiMock mock = new AddressApiMock();
        Test.setMock(HttpCallout.class, mock);

        Account acct = new Account(
            Name = 'No Street Account',
            BillingCity = 'Springfield',
            BillingPostalCode = '12345',
            BillingCountry = 'US'
            // BillingStreet deliberately left blank
        );

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        System.assertEquals('SKIPPED', result.status);
        System.assertEquals(false, result.changed);
        System.assertEquals(
            0,
            mock.capturedRequests.size(),
            'A blank BillingStreet must not trigger any callout'
        );
    }

    @isTest
    public static void testNonOkResponseThrows() {
        AddressApiMock mock = new AddressApiMock();
        Test.setMock(HttpCallout.class, mock);

        HttpResponse errorResponse = new HttpResponse();
        errorResponse.setStatusCode(400);
        errorResponse.setStatus('Bad Request');
        errorResponse.setBody('{"error":"invalid payload"}');
        mock.setResponse(errorResponse);

        Account acct = new Account(
            Name = 'Test Account',
            BillingStreet = '123 Main St',
            BillingCity = 'Springfield',
            BillingPostalCode = '12345',
            BillingCountry = 'US'
        );

        Boolean threw = false;
        try {
            AddressVerificationService.verify(acct);
        } catch (AddressVerificationService.AddressVerificationException e) {
            threw = true;
            System.assertTrue(
                e.getMessage().contains('400'),
                'Exception message must contain the status code, was: ' + e.getMessage()
            );
        }
        System.assertTrue(
            threw,
            'A non-200 response must throw AddressVerificationException'
        );
    }

    @isTest
    public static void testVerifiedResponseLeavesAccountUntouched() {
        AddressApiMock mock = new AddressApiMock();
        Test.setMock(HttpCallout.class, mock);

        HttpResponse okResponse = new HttpResponse();
        okResponse.setStatusCode(200);
        okResponse.setStatus('200 OK');
        okResponse.setBody(
            '{"status":"VERIFIED","address":{"street":"123 Main St","city":"Springfield","postalCode":"12345","country":"US"}}'
        );
        mock.setResponse(okResponse);

        Account acct = new Account(
            Name = 'Test Account',
            BillingStreet = '123 Main St',
            BillingCity = 'Springfield',
            BillingPostalCode = '12345',
            BillingCountry = 'US'
        );

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        System.assertEquals('VERIFIED', result.status);
        System.assertEquals(false, result.changed);
        System.assertEquals('123 Main St', acct.BillingStreet);
        System.assertEquals('Springfield', acct.BillingCity);
        System.assertEquals('12345', acct.BillingPostalCode);
        System.assertEquals('US', acct.BillingCountry);

        assertRequestContract(mock.capturedRequests.get(0), acct);
