public class PicklistService {

    public class PicklistServiceException extends Exception {
    }

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object and field API names must not be null or blank.');
        }

        // Resolve object name case-insensitively
        String objectName = null;
        Map<String, Schema.DescribeSObjectResult> globalObjects = Schema.getGlobalObjects();
        for (String obj : globalObjects.keySet()) {
            if (obj.equalsIgnoreCase(objectApiName)) {
                objectName = obj;
                break;
            }
        }
        if (objectName == null) {
            throw new PicklistServiceException('Object not found: ' + objectApiName);
        }

        // Resolve field name case-insensitively
        Schema.DescribeSObjectResult describeResult = Schema.describeSObjects(new String[]{objectName})[0];
        Map<String, Schema.SObjectField> fields = describeResult.fields.getMap();
        String fieldName = null;
        for (String f : fields.keySet()) {
            if (f.equalsIgnoreCase(fieldApiName)) {
                fieldName = f;
                break;
            }
        }
        if (fieldName == null) {
            throw new PicklistServiceException('Field not found on object ' + objectName + ': ' + fieldApiName);
        }

        Schema.DescribeFieldResult fieldDescribe = fields.get(fieldName).getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();

        if (fieldType != Schema.DisplayType.Picklist && fieldType != Schema.DisplayType.MultiPicklist) {
            throw new PicklistServiceException('Field is not a picklist or multi-select picklist: ' + fieldApiName);
        }

        List<Option> result = new List<Option>();
        for (Integer i = 0; i < fieldDescribe.getPicklistValues().size(); i++) {
            var pv = fieldDescribe.getPicklistValues().get(i);
            if (pv.isActive()) {
                result.add(new Option(
                    pv.getName(),
                    pv.getLabel(),
                    pv.isDefaultValue()
                ));
            }
        }

        return result;
    }
}
