public class AccountScoringJob implements Queueable {
    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        // Defensive copy: never mutate the caller's list
        this.accountIds = (accountIds == null) ? new List<Id>() : new List<Id>(accountIds);
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return Job.enqueue(new AccountScoringJob(accountIds));
    }

    public void execute(QueueableContext context) {
        // Nothing to process for an empty job (e.g. execute(null) on an empty instance)
        if (accountIds.isEmpty()) {
            return;
        }

        // Process at most the first 200 accounts
        Integer batchSize = Math.min(200, accountIds.size());
        List<Id> batchIds = new List<Id>();
        for (Integer i = 0; i < batchSize; i++) {
            batchIds.add(accountIds.get(i));
        }

        // Remove processed Ids; the remainder is carried forward in the chain
        List<Id> remaining = new List<Id>();
        for (Integer i = batchSize; i < accountIds.size(); i++) {
            remaining.add(accountIds.get(i));
        }
        accountIds.clear();
        accountIds.addAll(remaining);

        // One SOQL query
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
        ];

        // Compute Rating from AnnualRevenue
        List<Account> toUpdate = new List<Account>();
        for (Account acc : accounts) {
            Decimal revenue = acc.AnnualRevenue;
            if (revenue == null) {
                acc.Rating = 'Cold';
            } else if (revenue >= 1000000) {
                acc.Rating = 'Hot';
            } else if (revenue >= 100000) {
                acc.Rating = 'Warm';
            } else {
                acc.Rating = 'Cold';
            }
            toUpdate.add(acc);
        }

        // One DML statement
        if (!toUpdate.isEmpty()) {
            Database.update(toUpdate, false);
        }

        // Chain the remaining accounts, if any
        if (!accountIds.isEmpty()) {
            Job.enqueue(new AccountScoringJob(accountIds));
        }
    }
}
