global class LogPurgeJob implements Schedulable {
    // No-argument constructor required by the Schedulable interface.
    public LogPurgeJob() {
    }

    global void execute(SchedulableContext sc) {
        // Purge integration logs older than 30 days. ERROR logs are retained
        // longer and are only purged once they are older than 180 days.
        DateTime thirtyDaysAgo = DateTime.now().addDays(-30);
        DateTime oneHundredEightyDaysAgo = DateTime.now().addDays(-180);

        Integer batchSize = 200;
        List<FB_Integration_Log__c> batch = new List<FB_Integration_Log__c>();

        for (FB_Integration_Log__c log : Database.query([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :thirtyDaysAgo
              AND (Level__c != 'ERROR' OR CreatedDate < :oneHundredEightyDaysAgo)
        ])) {
            batch.add(log);
            if (batch.size() >= batchSize) {
                Database.delete(batch, false);
                batch.clear();
            }
        }

        if (!batch.isEmpty()) {
            Database.delete(batch, false);
        }
    }

    /**
     * Schedules the purge job to run every night at 02:00.
     *
     * @return the Id of the scheduled CronTrigger.
     */
    public static Id scheduleNightly() {
        LogPurgeJob job = new LogPurgeJob();
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', job);
    }
}
