public with sharing class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<SObject> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }

    public override void beforeInsert(List<SObject> newRecords) {
        validateAmountNotNegative(newRecords);
    }

    public override void beforeUpdate(List<SObject> newRecords, List<SObject> oldRecords) {
        validateAmountNotNegative(newRecords);

        if (oldRecords == null) {
            return;
        }

        Map<Id, SObject> oldById = new Map<Id, SObject>();
        for (SObject oldRecord : oldRecords) {
            oldById.put((Id) oldRecord.get('Id'), oldRecord);
        }

        for (SObject record : newRecords) {
            SObject oldRecord = oldById.get((Id) record.get('Id'));
            if (oldRecord == null) {
                continue;
            }

            if ('Closed Won'.equals((String) oldRecord.get('StageName'))) {
                Decimal oldAmount = (Decimal) oldRecord.get('Amount');
                Decimal newAmount = (Decimal) record.get('Amount');
                if (amountChanged(oldAmount, newAmount)) {
                    fflib_SObjectDomain.error('Amount cannot change on a won opportunity.', record, 'Amount');
                }
            }
        }
    }

    private void validateAmountNotNegative(List<SObject> records) {
        for (SObject record : records) {
            Decimal amount = (Decimal) record.get('Amount');
            if (amount != null && amount < 0) {
                fflib_SObjectDomain.error('Amount cannot be negative.', record, 'Amount');
            }
        }
    }

    private static Boolean amountChanged(Decimal oldAmount, Decimal newAmount) {
        if (oldAmount == null && newAmount == null) {
            return false;
        }
        if (oldAmount == null || newAmount == null) {
            return true;
        }
        return oldAmount.compareTo(newAmount) != 0;
    }
}
