        return Contact.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        Schema.DescribeSObjectResult describe = Contact.SObjectType.getDescribe();
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>();
        fields.add(describe.fields.getMap().get('Id'));
        fields.add(describe.fields.getMap().get('FirstName'));
        fields.add(describe.fields.getMap().get('LastName'));
        fields.add(describe.fields.getMap().get('Email'));
        fields.add(describe.fields.getMap().get('Title'));
        fields.add(describe.fields.getMap().get('AccountId'));
        return fields;
    }

    public List<Contact> selectById(Set<Id> contactIds) {
        if (contactIds == null || contactIds.isEmpty()) {
            return new List<Contact>();
        }

        List<Schema.SObjectField> fields = getSObjectFieldList();
        StringBuilder fieldNames = new StringBuilder();
        for (Integer i = 0; i < fields.size(); i++) {
            fieldNames.append(fields[i].getName());
            if (i < fields.size() - 1) {
                fieldNames.append(',');
            }
        }

        String query = 'SELECT ' + fieldNames.toString() + ' FROM Contact WHERE Id IN :contactIds';
        return (List<Contact>) Database.query(query);
    }
