public class CasePriorityHandler {
    private CasePriorityHandler() {}

    public static void handleTrigger(List<Case> newCases) {
        // Collect account IDs first to avoid SOQL limits in batches of up to 200
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        Map<Id, Account> accountsById = new Map<Id, Account>();
        for (Account acct : [SELECT Rating FROM Account WHERE Id IN :accountIds]) {
            accountsById.put(acct.Id, acct);
        }

        for (Case c : newCases) {
            if (c.AccountId != null) {
                Account acct = accountsById.get(c.AccountId);
                if (acct != null && acct.Rating == 'Hot') {
                    c.Priority = 'High';
                }
            }
        }
    }
}
