/**
 * DealEventPublisher
 *
 * Publishes one Deal_Stage_Change__e platform event per Opportunity so the data
 * warehouse can react to stage changes.
 *
 * Returns one Database.SaveResult per input opportunity, in the same order as
 * the input list. Because EventBus.publishAll returns a SaveResult for every
 * event (in input order), the caller can inspect isSuccess()/getErrors() to
 * know exactly which event failed.
 *
 * Bulk-safe for the up-to-200 opportunities passed from the Opportunity trigger
 * handler. A null or empty list publishes nothing and returns an empty list.
 *
 * Deviation from the per-record EventBus.publish loop:
 *   Calling EventBus.publish once per record counts as a DML statement. With up
 *   to 200 opportunities that exceeds the 150-statement per-transaction limit
 *   (Too many DML statements: 151). To stay correct and production-safe this
 *   implementation uses the bulk-safe EventBus.publishAll, which publishes all
 *   events in a single call and still returns one SaveResult per event in the
 *   same order as the input, preserving per-event failure visibility.
 */
public class DealEventPublisher {

    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        // Null/empty input: publish nothing and return an empty list.
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();
        for (Opportunity opp : opportunities) {
            Deal_Stage_Change__e evt = new Deal_Stage_Change__e();
            evt.Opportunity_Id__c = String.valueOf(opp.Id); // 18-character Id
            evt.Stage__c = opp.StageName;
            evt.Amount__c = opp.Amount;
            events.add(evt);
        }

        // Bulk-safe single publish call. Results are returned in the same order
        // as the input events, matching the input list order.
        Object[] eventArray = new Object[events.size()];
        for (Integer i = 0; i < events.size(); i++) {
            eventArray[i] = events[i];
        }
        return EventBus.publishAll(eventArray);
    }
}
```

