public with sharing class LineItemDiscountHandler {
    /**
     * Sets the standard product discount on new lines that have no explicit
     * Discount. Lines that already have a Discount (including 0) keep it.
     *
     * Product families are resolved with a single bulk SOQL so the query count
     * does not scale with the number of lines (e.g. a 200-line CPQ quote). The
     * discount rule itself still lives entirely in PricingRules.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> lineItems) {
        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem line : lineItems) {
            if (line.Discount == null && line.Product2Id != null) {
                productIds.add(line.Product2Id);
            }
        }

        Map<Id, String> familyByProduct = new Map<Id, String>();
        if (!productIds.isEmpty()) {
            for (Product2 p : [SELECT Id, Family FROM Product2 WHERE Id IN :productIds]) {
                familyByProduct.put(p.Id, p.Family);
            }
        }

        for (OpportunityLineItem line : lineItems) {
            if (line.Discount == null) {
                String family = familyByProduct.get(line.Product2Id);
                line.Discount = PricingRules.standardDiscountForFamily(family);
            }
        }
    }
}
