import { LightningElement, track } from 'lwc';
import searchContacts from 'ContactController/searchContacts';

export default class ContactSearch extends LightningElement {
    @track searchTerm = '';
    @track results = [];
    @track error = null;

    _requestId = 0;
    _pendingRequestId = 0;
    _searchTimeout = null;
    _disconnected = false;

    connectedCallback() {
        this._disconnected = false;
        this._requestId = 0;
        this._pendingRequestId = 0;
    }

    disconnectedCallback() {
        this._disconnected = true;
        if (this._searchTimeout) {
            clearTimeout(this._searchTimeout);
            this._searchTimeout = null;
        }
        this._pendingRequestId = 0;
    }

    handleChange(event) {
        if (this._disconnected) {
            return;
        }

        const rawValue = event.target.value ?? '';
        const term = rawValue.trim();

        this.searchTerm = rawValue;
        this._cancelPending();

        if (term.length < 2) {
            this.results = [];
            this.error = null;
            return;
        }

        this._searchTimeout = setTimeout(() => this._search(term), 300);
    }

    _cancelPending() {
        if (this._searchTimeout) {
            clearTimeout(this._searchTimeout);
            this._searchTimeout = null;
        }
        this._pendingRequestId = 0;
    }

    _search(term) {
        if (this._disconnected) {
            return;
        }

        this._requestId += 1;
        const requestId = this._requestId;
        this._pendingRequestId = requestId;

        searchContacts({ searchTerm: term }).then((result) => {
            if (this._disconnected || requestId !== this._pendingRequestId) {
                return;
            }
            this.error = null;
            this.results = result ?? [];
        }).catch((error) => {
            if (this._disconnected || requestId !== this._pendingRequestId) {
                return;
            }
            this.results = [];
            const message = error && error.body && error.body.message
                ? error.body.message
                : error && error.message
                ? error.message
                : String(error);
            this.error = { body: { message } };
        });
    }
}
