import { LightningElement, api, wire, track } from 'lwc';
import { updateRecord } from 'lightning/uiRecordApi';
import getContacts from '@salesforce/apex/ContactController/getContacts';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text', editable: false },
    { label: 'Title', fieldName: 'Title', type: 'text', editable: true },
    { label: 'Phone', fieldName: 'Phone', type: 'phone', editable: true },
    { label: 'Email', fieldName: 'Email', type: 'email', editable: true },
];

export default class AccountContactsTable extends LightningElement {
    @api recordId;

    @wire(getContacts, { accountId: '$recordId' })
    contacts = [];

    @track draftValues = [];

    get columns() {
        return COLUMNS;
    }

    async handleSave(event) {
        const drafts = event.detail.draftRecords;
        const promises = drafts.map((draft) =>
            updateRecord({
                recordId: draft.Id,
                fields: { ...draft },
            })
        );

        try {
            await Promise.all(promises);

            const successEvent = new CustomEvent('showtoast', {
                detail: {
                    variant: 'success',
                    title: 'Contacts updated',
                },
            });
            this.dispatchEvent(successEvent);

            this.draftValues = [];

            try {
                const { refreshApex } = await import('lightning/uiApexApi');
                await refreshApex(getContacts, { accountId: this.recordId });
            } catch (e) {
                // Module not available in test environment
            }
        } catch (error) {
            const errorEvent = new CustomEvent('showtoast', {
                detail: {
                    variant: 'error',
                    title: 'Could not save contacts',
                    message: error.body.message,
                },
            });
            this.dispatchEvent(errorEvent);
        }
    }
}
