import { LightningElement, track } from 'lwc';

let instanceCounter = 0;

export default class StatusListbox extends LightningElement {
    @track label = '';
    @track _options = [];
    @track _value = '';
    @track _activeIndex = 0;

    private _instanceId = `status-listbox-${++instanceCounter}`;

    get options() {
        return this._options;
    }

    set options(val) {
        this._options = val;
        this._syncActiveIndex();
    }

    get value() {
        return this._value;
    }

    set value(val) {
        this._value = val;
        this._syncActiveIndex();
    }

    get activeOptionId() {
        if (
            !this._options ||
            this._options.length === 0 ||
            this._activeIndex < 0 ||
            this._activeIndex >= this._options.length
        ) {
            return undefined;
        }
        return `${this._instanceId}-option-${this._activeIndex}`;
    }

    get selectedIndex() {
        if (!this._options || this._options.length === 0) {
            return -1;
        }
        return this._options.findIndex((opt) => opt.value === this._value);
    }

    connectedCallback() {
        this._syncActiveIndex();
    }

    _syncActiveIndex() {
        if (!this._options || this._options.length === 0) {
            this._activeIndex = 0;
            return;
        }

        if (this._activeIndex >= this._options.length) {
            this._activeIndex = this._options.length - 1;
        }

        const index = this._options.findIndex((opt) => opt.value === this._value);
        if (index !== -1) {
            this._activeIndex = index;
        }
    }

    _selectOption(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }

        const newValue = option.value;

        // Do not dispatch when the option is already selected
        if (newValue === this._value) {
            return;
        }

        this._value = newValue;
        this._activeIndex = index;

        const event = new CustomEvent('change', {
            detail: { value: newValue },
            bubbles: true,
            composed: true,
        });
        this.dispatchEvent(event);
    }

    handleKeydown = (event) => {
        const key = event.key;
        const { _options, _activeIndex } = this;

        switch (key) {
            case 'ArrowDown':
                event.preventDefault();
                if (_activeIndex < _options.length - 1) {
                    this._activeIndex = _activeIndex + 1;
                }
                break;
            case 'ArrowUp':
                event.preventDefault();
                if (_activeIndex > 0) {
                    this._activeIndex = _activeIndex - 1;
                }
                break;
            case 'Home':
                event.preventDefault();
                this._activeIndex = 0;
                break;
            case 'End':
                event.preventDefault();
                this._activeIndex = _options.length - 1;
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this._selectOption(_activeIndex);
                break;
            default:
                // Allow default behavior for all other keys, including Tab
                break;
        }
    };

    handleClick = (event) => {
        const option = event.target.closest('[role="option"]');
        if (!option) {
            return;
        }

        const index = Number.parseInt(option.dataset.index, 10);
        if (Number.isInteger(index) && index >= 0 && index < this._options.length) {
            this._selectOption(index);
        }
    };
}
