/**
 * RecurringGiftService
 *
 * Records monthly recurring-gift sign-ups from a donation form as NPSP
 * Enhanced Recurring Donation records. NPSP owns the generation of the
 * installment Opportunities; this service only creates the recurring donation
 * parent records.
 *
 * Bulk-safe design: every request is validated before any DML (and before any
 * SOQL), the donor accounts are resolved with a single SOQL query, and all
 * recurring donations are inserted with a single DML statement. A 200-request
 * call therefore uses at most one SOQL query and one DML statement.
 */
public class RecurringGiftService {

    /**
     * Thrown when a gift request fails validation.
     */
    public class RecurringGiftException extends Exception {}

    /**
     * Input sent by the donation form for one monthly recurring gift.
     */
    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31; 31 means the last day of the month
        public Date startDate;
        public Integer installments;  // null or 0 = open-ended
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    /**
     * Create one Enhanced Recurring Donation per request and return the new IDs
     * in request order.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        // Null or empty input -> nothing to do.
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // ------------------------------------------------------------------
        // 1. Validate every request before any DML (and before any SOQL).
        // ------------------------------------------------------------------
        Set<Id> contactIds = new Set<Id>();
        for (GiftRequest req : requests) {
            if (req.contactId == null) {
                throw new RecurringGiftException('contactId is required.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException('amount must be greater than zero.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException('dayOfMonth must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException('startDate is required.');
            }
            contactIds.add(req.contactId);
        }

        // ------------------------------------------------------------------
        // 2. Resolve each donor's organization (account) with one SOQL.
        // ------------------------------------------------------------------
        Map<Id, Id> contactToAccount = new Map<Id, Id>();
        if (!contactIds.isEmpty()) {
            for (Contact donor : [
                    SELECT Id, AccountId
                    FROM Contact
                    WHERE Id IN :contactIds
            ]) {
                contactToAccount.put(donor.Id, donor.AccountId);
            }
        }

        // ------------------------------------------------------------------
        // 3. Build the recurring donation records.
        // ------------------------------------------------------------------
        List<npe03__Recurring_Donation__c> gifts = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest req : requests) {
            npe03__Recurring_Donation__c gift = new npe03__Recurring_Donation__c();

            // Donor and money.
            gift.npe03__Contact__c = req.contactId;
            gift.npe03__Organization__c = contactToAccount.get(req.contactId);
            gift.npe03__Amount__c = req.amount;

            // Recurring donation schedule (NPSP standard fields).
            gift.npe03__Installment_Period__c = 'Monthly';
            gift.npe03__Schedule_Type__c = 'Recurring';
            gift.npe03__Open_Ended_Status__c = (req.installments == null || req.installments == 0)
                    ? 'Open Ended' : 'Scheduled';
            if (req.installments == null || req.installments == 0) {
                gift.npe03__Installments__c = null;
            } else {
                gift.npe03__Installments__c = req.installments;
            }
            gift.npe03__Date_Established__c = req.startDate;
            gift.npe03__Next_Payment_Date__c = req.startDate;

            // Installment schedule NPSP uses to generate installment
            // Opportunities. The form's 31 means "last day of the month".
            gift.npsp__RecurringType__c = 'Monthly';
            gift.npsp__InstallmentFrequency__c = 'Monthly';
            gift.npsp__Day_of_Month__c = req.dayOfMonth;
            gift.npsp__Always_Use_Last_Day_Of_Month__c = (req.dayOfMonth == 31);
            gift.npsp__StartDate__c = req.startDate;
            gift.npsp__Status__c = 'Active';
            gift.npsp__PaymentMethod__c = req.paymentMethod;

            // Fixed-length donations carry an end date; open-ended ones do not.
            if (req.installments != null && req.installments > 0) {
                gift.npsp__EndDate__c = req.startDate.addMonths(req.installments - 1);
            }

            gifts.add(gift);
        }

        // ------------------------------------------------------------------
        // 4. Insert with a single DML statement and return IDs in request order.
        // ------------------------------------------------------------------
        insert gifts;

        List<Id> ids = new List<Id>();
        for (npe03__Recurring_Donation__c gift : gifts) {
            ids.add(gift.Id);
        }
        return ids;
    }
}
