public with sharing class OpportunityErpSyncFinalizer 
    implements TriggerAction.DmlFinalizer {

    public void execute(FinalizerHandler.Context context) {
        Set<Id> idsToSync = TA_Opportunity_CollectForErpSync.getIdsToSync();

        if (idsToSync != null && !idsToSync.isEmpty()) {
            // Exactly one job per DML operation carrying every Id collected
            // by the trigger action during that operation.
            OpportunityErpSyncJob job = new OpportunityErpSyncJob(idsToSync);
            System.enqueueJob(job);
        }

        // Clear the collected Ids so the next DML operation begins fresh.
        // Enqueuing a Queueable job is not a DML operation.
        TA_Opportunity_CollectForErpSync.clearIdsToSync();
    }
}
