    }

    /**
     * beforeUpdate: only Contacts whose Email or AccountId changed are evaluated.
     * A Contact never conflicts with itself, so legacy duplicates do not block
     * unrelated edits. Bulk-safe: a single SOQL query per execution.
     */
    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Contact> oldById = new Map<Id, Contact>();
        for (SObject so : triggerOld) {
            Contact old = (Contact) so;
            oldById.put(old.Id, old);
        }

        List<Contact> contactsToCheck = new List<Contact>();
        for (SObject so : triggerNew) {
            Contact c = (Contact) so;
            Contact old = oldById.get(c.Id);
            if (old == null) {
                continue;
            }
            Boolean emailChanged = !String.valueOf(c.Email).equals(String.valueOf(old.Email));
            Boolean accountChanged = !String.valueOf(c.AccountId).equals(String.valueOf(old.AccountId));
            if ((emailChanged || accountChanged) && c.AccountId != null && c.Email != null) {
                contactsToCheck.add(c);
            }
        }

        evaluateDuplicateEmails(contactsToCheck);
    }

    /**
     * Shared bulk-safe duplicate check.
     * - One SOQL query loads existing Contacts for the involved Accounts.
     * - existingEmailsByAccount holds lower-cased emails already on each Account
     *   (excluding the Contacts being evaluated, so a Contact never conflicts
     *   with itself).
     * - seenByAccount is seeded with existing emails, then Contacts are processed
     *   in trigger order: the first Contact in the list is accepted and each later
     *   Contact sharing an Account and email is rejected.
     */
    private void evaluateDuplicateEmails(List<Contact> contactsToCheck) {
        if (contactsToCheck.isEmpty()) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();
        Set<Id> selfIds = new Set<Id>();
        for (Contact c : contactsToCheck) {
            accountIds.add(c.AccountId);
            selfIds.add(c.Id);
        }

        // Single SOQL query: existing Contacts on the involved Accounts,
        // excluding the Contacts being evaluated so a Contact never conflicts
        // with itself (e.g. a case-only email change on a legacy duplicate).
        Map<Id, Set<String>> emailsByAccount = new Map<Id, Set<String>>();
        for (Contact existing :
            [SELECT Id, AccountId, Email
             FROM Contact
             WHERE AccountId IN :accountIds
               AND Email != null
               AND Id NOT IN :selfIds]) {
            Set<String> accountEmails = emailsByAccount.get(existing.AccountId);
            if (accountEmails == null) {
                accountEmails = new Set<String>();
                emailsByAccount.put(existing.AccountId, accountEmails);
            }
            accountEmails.add(existing.Email.toLowerCase());
        }

        // Seed the in-transaction seen sets with existing emails, then process
        // in trigger order so the first Contact in the list wins.
        Map<Id, Set<String>> seenByAccount = new Map<Id, Set<String>>();
        for (Id accId : emailsByAccount.keySet()) {
            seenByAccount.put(accId, new Set<String>(emailsByAccount.get(accId)));
        }

        for (Contact c : contactsToCheck) {
            Set<String> seen = seenByAccount.get(c.AccountId);
            if (seen == null) {
                seen = new Set<String>();
                seenByAccount.put(c.AccountId, seen);
            }
            String emailLower = c.Email.toLowerCase();
            if (seen.contains(emailLower)) {
                c.addError(DUPLICATE_EMAIL_ERROR);
            } else {
                seen.add(emailLower);
            }
        }
    }
}
