public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    /*
     * Tracks Opportunities that already received an Amount changed Task within the
     * current transaction. Static state is reset at the start of each transaction,
     * so this gives per-transaction deduplication.
     *
     * TA_Opportunity_RoundAmount (Order 20) re-updates Opportunities in the same
     * transaction, which re-fires the after-update trigger. Without this deduplication
     * the rounding's Amount change would create a duplicate Task. The rounding is a
     * consequence of the user's change, not a separate one, so at most one Task per
     * Opportunity per transaction is required.
     */
    private static Set<Id> loggedAmountChangeOpportunities = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        Integer size = triggerNew.size();
        List<Task> tasks = new List<Task>();

        for (Integer i = 0; i < size; i++) {
            Opportunity opp = triggerNew[i];
            Opportunity old = (triggerOld != null && triggerOld.size() == size)
                    ? triggerOld[i]
                    : null;

            if (old == null) {
                continue;
            }

            // Only act when Amount actually changed.
            if (opp.Amount == old.Amount) {
                continue;
            }

            // Skip if already logged earlier in this transaction (e.g. from a
            // re-trigger caused by the rounding action).
            if (loggedAmountChangeOpportunities.contains(opp.Id)) {
                continue;
            }

            loggedAmountChangeOpportunities.add(opp.Id);

            tasks.add(new Task(
                Subject = 'Amount changed',
                WhatId = opp.Id,
                Status = 'Completed'
            ));
        }

        // One task insert per trigger execution, bulk-safe.
        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
