/**
 * TA_Contact_InheritMailingAddress
 *
 * Trigger action (before insert, Order 10). When a new Contact has a parent
 * Account and all four mailing address fields are blank, copies the Account's
 * billing address into the Contact. A Contact with any mailing field already
 * filled in keeps its own address. Contacts without an Account are left alone.
 *
 * The parent Account is read from the shared map populated by
 * TA_Contact_Queries.Service, so this action issues no queries itself.
 */
public class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accounts = TA_Contact_Queries.getInstance().accountsById;
        for (SObject s : triggerNew) {
            Contact c = (Contact) s;

            if (c.AccountId == null) {
                continue;
            }
            Account acc = accounts.get(c.AccountId);
            if (acc == null) {
                continue;
            }
            // Keep any mailing address that is already populated.
            if (c.MailingStreet != null || c.MailingCity != null ||
                c.MailingPostalCode != null || c.MailingCountry != null) {
                continue;
            }

            c.MailingStreet = acc.BillingStreet;
            c.MailingCity = acc.BillingCity;
            c.MailingPostalCode = acc.BillingPostalCode;
            c.MailingCountry = acc.BillingCountry;
        }
    }
}
